import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Context API', () => {
  test('Initially displays "Current theme: light"', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#theme-display');
if (!el) throw new Error('No #theme-display found');
const text = el.textContent;
if (!text.includes('Current theme:') || !text.includes('light'))
  throw new Error('Should show "Current theme: light" initially');
  });

  test('Toggle button switches to dark theme', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#toggle-btn');
if (!btn) throw new Error('No #toggle-btn found');
btn.click();
await tick();
const el = root.querySelector('#theme-display');
if (!el.textContent.includes('dark'))
  throw new Error('Should show "dark" after toggling');
  });

  test('Toggling again returns to light', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#toggle-btn');
btn.click();
await tick();
const el = root.querySelector('#theme-display');
if (!el.textContent.includes('light'))
  throw new Error('Should show "light" after toggling back');
  });

  test('ThemeDisplay reads from Context (no theme prop)', async () => {
    const { container: root } = render(<App />);
    const display = root.querySelector('#theme-display');
if (!display) throw new Error('No #theme-display');
if (display.textContent.includes('undefined'))
  throw new Error('Theme value is undefined — make sure you provide context value');
  });
});
